      "parameters": {
        "type": "object",
        "properties": {
          "order_id": {
            "type": "string",
            "description": "Order id."
          }
        },
        "required": [
          "order_id"
        ]
      },
      "return": {
        "type": "object",
        "additionalProperties": {}
      }
    }
  },
  {
