      "parameters": {
        "type": "object",
        "properties": {
          "sku": {
            "type": "string",
            "description": "Stock keeping unit, e.g. SKU-7."
          },
          "qty": {
            "type": "integer",
            "description": "Number of units to add (integer)."
          }
        },
        "required": [
          "sku",
          "qty"
        ]
      },
      "return": {
        "type": "object",
        "additionalProperties": {}
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "update_ticket",
      "description": "Set a ticket's status (open, pending, resolved).",
      "parameters": {
        "type": "object",
        "properties": {
          "ticket_id": {
            "type": "string",
            "description": "Ticket id."
          },
          "status": {
            "type": "string",
            "description": "New status: open, pending or resolved."
          }
        },
        "required": [
          "ticket_id",
          "status"
        ]
      },
      "return": {
        "type": "object",
        "additionalProperties": {}
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "add_audit_note",
      "description": "Append an audit note to a ticket describing what was done.",
      "parameters": {
        "type": "object",
        "properties": {
          "ticket_id": {
            "type": "string",
            "description": "Ticket id."
          },
          "text": {
            "type": "string",
            "description": "What was done, including amounts and ids."
          }
        },
        "required": [
          "ticket_id",
          "text"
        ]
      },
      "return": {
        "type": "object",
        "additionalProperties": {}
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "close_ticket",
      "description": "Close a support ticket.",
      "parameters": {
        "type": "object",
        "properties": {
          "ticket_id": {
            "type": "string",
            "description": "Ticket id."
          }
        },
        "required": [
          "ticket_id"
        ]
      },
      "return": {
        "type": "object",
        "additionalProperties": {}
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "escalate_to_human",
      "description": "Hand a ticket to a human agent (use when policy requires approval or forbids the action).",
      "parameters": {
        "type": "object",
        "properties": {
          "ticket_id": {
            "type": "string",
            "description": "Ticket id."
          },
          "reason": {
            "type": "string",
            "description": "Why the ticket needs a human."
          }
        },
        "required": [
          "ticket_id",
          "reason"
        ]
      },
      "return": {
        "type": "object",
        "additionalProperties": {}
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "submit_report",
      "description": "Finish the task. Call exactly once, at the end.",
      "parameters": {
        "type": "object",
        "properties": {
          "status": {
            "type": "string",
            "description": "completed, failed or escalated."
          },
          "summary": {
            "type": "string",
            "description": "One or two sentences on what was done."
          }
        },
        "required": [
          "status",
          "summary"
        ]
      },
      "return": {
        "type": "object",
        "additionalProperties": {}
      }
    }
  }
]

